// Linear SVM fan-fault detector (normal = 0, fault = 1)
// Generated by pipeline.py (shared split, C = 1.0).
// Features come from features.py. Input: 1000 samples at 1 kHz of the acceleration
// magnitude sqrt(ax^2 + ay^2 + az^2) in m/s^2 (raw counts * 9.80665 / 4096, +/-8 g range).
// Feature order MUST be:
//   rms, peak, std, kurtosis, crest_factor, band_5_25hz, band_25_75hz, band_75_200hz, band_200_500hz
#pragma once

#define N_FEATURES 9

static const float SVM_MEAN[N_FEATURES] = {
  9.20654964e+00f, 9.62341118e+00f, 1.90294906e-01f,
  -3.49870950e-01f, 1.04525602e+00f, 3.73594339e-05f,
  2.02450249e-03f, 1.26572791e-04f, 1.36364242e-05f
};

static const float SVM_SCALE[N_FEATURES] = {
  8.13969318e-03f, 2.93839633e-01f, 1.57366410e-01f,
  2.13093424e+00f, 3.11235432e-02f, 9.89711407e-05f,
  3.45658627e-03f, 5.66731796e-05f, 5.78329627e-06f
};

static const float SVM_COEF[N_FEATURES] = {
  -4.47602570e-01f, 3.13136160e-01f, -5.62192142e-01f,
  -1.47327220e+00f, 3.36876154e-01f, 1.81449965e-01f,
  -9.34623361e-01f, 1.04004359e+00f, 2.57158518e+00f
};

static const float SVM_INTERCEPT = 1.62843621e+00f;

// Returns signed decision score (>= 0.0f means fault, < 0.0f means normal).
static inline float svm_predict_score(const float *x) {
  float s = SVM_INTERCEPT;
  for (int i = 0; i < N_FEATURES; i++) s += SVM_COEF[i] * (x[i] - SVM_MEAN[i]) / SVM_SCALE[i];
  return s;
}

static inline int svm_predict(const float *x) {
  return svm_predict_score(x) >= 0.0f ? 1 : 0;
}
